 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    # The 2x2 objects remain fixed; their four diagonal neighbors circulate
    # clockwise, then continue outward along the corresponding diagonals.
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                blocks.append((r, c))
                for rr in (r, r + 1):
                    for cc in (c, c + 1):
                        out[rr][cc] = 2

    for r, c in blocks:
        pos = [(r - 1, c - 1), (r - 1, c + 2),
               (r + 2, c - 1), (r + 2, c + 2)]  # UL, UR, LL, LR
        vals = [grid[rr][cc] if 0 <= rr < h and 0 <= cc < w else 0 for rr, cc in pos]
        # Clockwise circulation: LL->UL, UL->UR, LR->LL, UR->LR.
        colors = [vals[2], vals[0], vals[3], vals[1]]
        dirs = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        for (rr, cc), color, (dr, dc) in zip(pos, colors, dirs):
            if color == 0 or not (0 <= rr < h and 0 <= cc < w):
                continue
            while 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
                rr += dr
                cc += dc
    return out
